text:
/* Canonical application color literals.
 * Scoped aliases remain beside their rules to preserve the cascade.
 * Primitives are source-qualified; do not override them for theme selection.
 */

/* History allowance pill: these aliases are consumed only by the mini meters. */
:root {
  --allowance-surface: var(--color-globals-card-3);
  --allowance-border: #ddd0f5;
  --allowance-shadow: 0 4px 14px rgba(124, 58, 237, 0.12);
  --allowance-value: #3b1f6b;
  --allowance-muted: #6b5a8e;
  --allowance-label: #6f6294;
  --allowance-icon-background: #ede4ff;
  --allowance-icon: #7c3aed;
  --allowance-track: #ebe2fa;
  --allowance-fill: var(--color-contacts-contacts-gradient-2);
  --allowance-bar-height: 5px;
  --allowance-meter-radius: 3px;
  --allowance-meter-shadow: none;
  --allowance-button: var(--allowance-icon-background);
  --allowance-button-text: var(--allowance-value);
  --allowance-button-hover: color-mix(
    in srgb,
    var(--allowance-button) 80%,
    var(--allowance-icon) 20%
  );
}
html[data-theme="dark"] {
  --allowance-surface: #0e0c1d;
  --allowance-border: #2a2745;
  --allowance-shadow: 0 0 24px rgba(167, 139, 250, 0.12);
  --allowance-value: var(--color-globals-card-3);
  --allowance-muted: #a9a5c4;
  --allowance-label: #8f8ab0;
  --allowance-icon-background: rgba(167, 139, 250, 0.16);
  --allowance-icon: #c4a8ff;
  --allowance-track: var(--allowance-border);
  --allowance-fill: linear-gradient(
    90deg,
    var(--color-landing-landing-accent-11),
    var(--color-history-h-pink-14)
  );
  --allowance-meter-shadow: 0 0 8px rgba(167, 139, 250, 0.55);
  --allowance-button: var(--allowance-icon-background);
  --allowance-button-text: var(--allowance-icon);
  --allowance-button-hover: color-mix(
    in srgb,
    var(--allowance-surface) 76%,
    var(--allowance-icon) 24%
  );
}
html[data-appearance="vercel"][data-theme="light"] {
  --allowance-surface: var(--color-globals-card-3);
  --allowance-border: #d6d6d6;
  --allowance-shadow: none;
  --allowance-value: #161616;
  --allowance-muted: #5c5c5c;
  --allowance-label: #6a6a6a;
  --allowance-icon-background: var(--allowance-value);
  --allowance-icon: var(--color-globals-card-3);
  --allowance-track: #e4e4e4;
  --allowance-fill: #2b2b2b;
  --allowance-bar-height: 4px;
  --allowance-meter-radius: 1px;
  --allowance-meter-shadow: none;
  --allowance-button: var(--allowance-track);
  --allowance-button-text: var(--allowance-value);
  --allowance-button-hover: var(--allowance-border);
}
html[data-appearance="vercel"][data-theme="dark"] {
  --allowance-surface: #121212;
  --allowance-border: #2b2b2b;
  --allowance-shadow: none;
  --allowance-value: var(--color-globals-card-3);
  --allowance-muted: #9a9a9a;
  --allowance-label: #8a8a8a;
  --allowance-icon-background: var(--color-pricing-ribbon-chalk-start);
  --allowance-icon: #e5e5e5;
  --allowance-track: var(--allowance-border);
  --allowance-fill: var(--allowance-icon);
  --allowance-bar-height: 2px;
  --allowance-meter-radius: 1px;
  --allowance-meter-shadow: none;
  --allowance-button: var(--allowance-icon-background);
  --allowance-button-text: var(--allowance-icon);
  --allowance-button-hover: var(--allowance-border);
}

/* Limit banner aliases follow all four existing appearance/theme combinations. */
:root {
  --color-limit-banner-lavender-stripe: #d97706;
  --color-limit-banner-nightbloom-stripe: #fbbf24;
  --color-limit-banner-chalk-stripe: #c2410c;
  --color-limit-banner-obsidian-stripe: #f59e0b;
  --limit-stripe: var(--color-limit-banner-lavender-stripe);
}
html[data-theme="dark"] {
  --limit-stripe: var(--color-limit-banner-nightbloom-stripe);
}
html[data-appearance="vercel"][data-theme="light"] {
  --limit-stripe: var(--color-limit-banner-chalk-stripe);
}
html[data-appearance="vercel"][data-theme="dark"] {
  --limit-stripe: var(--color-limit-banner-obsidian-stripe);
}
:root,
html[data-appearance="purple"][data-theme="light"],
html[data-appearance="purple"][data-theme="dark"],
html[data-appearance="vercel"][data-theme="light"],
html[data-appearance="vercel"][data-theme="dark"] {
  --limit-accent: var(--accent);
  --limit-accent-ink: var(--button-foreground);
  --limit-pip-off: color-mix(in srgb, var(--border) 70%, var(--card));
  --limit-glow: color-mix(in srgb, var(--accent) 16%, transparent);
}

/* Pricing ribbons and their matching Premium buttons share reference palettes. */
:root {
  --color-pricing-ribbon-lavender-end: #c26af0;
  --color-pricing-ribbon-lavender-fold: #4c2a9e;
  --color-pricing-ribbon-nightbloom-start: #8b6cf0;
  --color-pricing-ribbon-nightbloom-end: #c561ec;
  --color-pricing-ribbon-nightbloom-fold: #3f2692;
  --color-pricing-ribbon-chalk-start: #1f1f1f;
  --color-pricing-ribbon-chalk-end: #4a4a4a;
  --color-pricing-ribbon-chalk-fold: #000000;
  --color-pricing-ribbon-obsidian-end: #c8c8c8;
  --color-pricing-ribbon-obsidian-fold: #6f6f6f;
  --rb-shadow: rgba(0, 0, 0, 0.28);
  --rb1: var(--color-pricing-grad-12);
  --rb2: var(--color-pricing-ribbon-lavender-end);
  --rb-fold: var(--color-pricing-ribbon-lavender-fold);
  --rb-ink: #0a0a0a;
}
html[data-theme="dark"] {
  --rb1: var(--color-pricing-ribbon-nightbloom-start);
  --rb2: var(--color-pricing-ribbon-nightbloom-end);
  --rb-fold: var(--color-pricing-ribbon-nightbloom-fold);
  --rb-ink: #0a0a0a;
}
html[data-appearance="vercel"][data-theme="light"] {
  --rb1: var(--color-pricing-ribbon-chalk-start);
  --rb2: var(--color-pricing-ribbon-chalk-end);
  --rb-fold: var(--color-pricing-ribbon-chalk-fold);
  --rb-ink: var(--color-globals-card-3);
}
html[data-appearance="vercel"][data-theme="dark"] {
  --rb1: var(--color-appearance-control-preview-bg-9);
  --rb2: var(--color-pricing-ribbon-obsidian-end);
  --rb-fold: var(--color-pricing-ribbon-obsidian-fold);
  --rb-ink: var(--color-appearance-control-preview-bg-12);
}

