  --confirmation-accent-text: #6740d3;
  --confirmation-accent-soft: #eee7fc;
  --confirmation-ink: #ffffff;
}
html[data-theme="dark"] {
  --confirmation-bg: #0a0818;
  --confirmation-card: #15122b;
  --confirmation-tile: #1d1a32;
  --confirmation-border: #302b45;
  --confirmation-text: #f3f0fc;
  --confirmation-muted: #b7adce;
  --confirmation-accent: #7c56ef;
  --confirmation-accent-text: #a68aff;
  --confirmation-accent-soft: #261e4b;
}
html[data-appearance="vercel"][data-theme="light"] {
  --confirmation-bg: #fafafa;
  --confirmation-card: #ffffff;
  --confirmation-tile: #f5f5f5;
  --confirmation-border: #dedede;
  --confirmation-text: #171717;
  --confirmation-muted: #626262;
  --confirmation-accent: #242424;
  --confirmation-accent-text: #424242;
  --confirmation-accent-soft: #eaeaea;
}
html[data-appearance="vercel"][data-theme="dark"] {
  --confirmation-bg: #090909;
  --confirmation-card: #141414;
  --confirmation-tile: #1e1e1e;
  --confirmation-border: #303030;
  --confirmation-text: #f5f5f5;
  --confirmation-muted: #b0b0b0;
  --confirmation-accent: #e5e5e5;
  --confirmation-accent-text: #d4d4d4;
