}

/* Section boundaries share the active surface's muted text at 85% opacity. */
:root {
  --separator: color-mix(in srgb, var(--muted-foreground) 85%, transparent);
}

/* Neutral interaction paints: keep status colors and Premium gradients separate. */
html[data-themed][data-appearance="vercel"][data-theme="light"] {
  --neutral-primary-rest: #242424;
  --neutral-primary-hover: #404040;
  --neutral-primary-pressed: #303030;
  --neutral-control-hover: #e5e5e5;
  --neutral-control-pressed: #d8d8d8;
  --neutral-control-border-hover: #626262;
}
html[data-themed][data-appearance="vercel"][data-theme="dark"] {
  --neutral-primary-rest: #ededed;
  --neutral-primary-hover: #cccccc;
  --neutral-primary-pressed: #b8b8b8;
  --neutral-control-hover: #303030;
  --neutral-control-pressed: #3b3b3b;
  --neutral-control-border-hover: #aaaaaa;
}
